create table audio_variants (id uuid primary key, episode_id uuid not null references episodes(id) on delete cascade, fingerprint text not null, source_metadata jsonb not null default '{}', duration_ms bigint, processing_version text not null, observed_at timestamptz not null default now(), unique(episode_id,fingerprint));
create table skip_intervals (id uuid primary key, episode_id uuid not null references episodes(id) on delete cascade, audio_variant_id uuid not null references audio_variants(id) on delete cascade, start_ms bigint not null, end_ms bigint not null check(end_ms>start_ms), type text not null, confidence numeric(4,3) not null, verification_state text not null, evidence jsonb not null default '[]', model_version text, processing_version text not null, disputed boolean not null default false, reuse_count integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table skip_feedback (id uuid primary key, interval_id uuid references skip_intervals(id) on delete set null, profile_id uuid references listener_profiles(id) on delete set null, kind text not null, note text, created_at timestamptz not null default now());
create index skip_intervals_variant_range on skip_intervals(audio_variant_id,start_ms,end_ms);
